function command(c){if(!ready)return false;const r=state.issue(c);if(!r.ok)notify(r.reason);return r.ok;}
function followHero(){if(state)moveCamera([state.player.position.x,1,state.player.position.z],5.5);}
function returnFountain(){if(!state)return;const f=state.fountains.find(f=>f.team===state.player.team),p=state.nav.nearest(f.position,3);if(p&&command({type:'move',point:p}))notify('Герой направляется на фонтан');}
function approachCrystal(){const e=entities.get(state?.selected);if(!e)return;const p=xy(e.position),candidates=[];for(let i=0;i<16;i++){const a=i*Math.PI/8,q={x:p.x+Math.cos(a)*4,y:0,z:p.z+Math.sin(a)*4};if(state.nav.walkable(q))candidates.push(q);}candidates.sort((a,b)=>dist(a,state.player.position)-dist(b,state.player.position));for(const p of candidates)if(state.nav.find(state.player.position,p)){command({type:'move',point:p});followHero();return;}notify('К этому затвору пока нет доступного пути');}
function bindPlaytestUI(){$('follow-hero').onclick=followHero;$('return-fountain').onclick=returnFountain;$('visit-fountain').onclick=returnFountain;$('attack-hero').onclick=()=>command({type:'hero_attack',target:state.selected});$('damage-player').onclick=()=>{if(state){state.woundPlayer();notify('Здоровье и мана потрачены — на своём фонтане они восстановятся');}};$('test-closure').onclick=()=>{if(state){state.testBridgeClosure();matchPaused=false;$('pause-match').textContent='Ⅱ';followHero();notify('Герой на мосту. Закрытие через 3 секунды');}};$('skip-time').onclick=()=>{if(state)state.advanceTo(state.time+30);};$('reset-match').onclick=()=>{state?.reset();combatView?.reset();autoAttack=null;matchPaused=false;$('pause-match').textContent='Ⅱ';notify('Таймер сброшен. Оба моста закрыты');};$('pause-match').onclick=()=>{matchPaused=!matchPaused;$('pause-match').textContent=matchPaused?'▶':'Ⅱ';};$('toggle-bots').onchange=e=>{if(!state)return;state.botsEnabled=e.target.checked;if(!e.target.checked)for(const h of state.heroes)if(h!==state.player){h.path=[];h.goal=null;}};}
const svgNode=(name,attrs={})=>{const el=document.createElementNS('http://www.w3.org/2000/svg',name);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);return el;};
function setupPlaytest(){const mini=$('mini-map');mini.replaceChildren(svgNode('rect',{x:-100,y:-100,width:200,height:200,rx:5,fill:'#254c3e'}));const route=(r,color,width)=>svgNode('polyline',{points:r.map(p=>`${p.X},${-p.Y}`).join(' '),fill:'none',stroke:color,'stroke-width':width,'stroke-linejoin':'round'});mini.append(route(layout.river,'#35b5c3',10));for(const lane of Object.values(layout.lanes))mini.append(route(lane,'#c6bd92',5));for(const [i,b]of layout.energy_bridges.entries()){const p=xy(b.position),pin=svgNode('circle',{id:'mini-bridge-'+i,cx:p.x,cy:p.z,r:6,fill:i===0?'#ffdd83':'#d284fa',class:'mini-bridge',stroke:'#fff','stroke-width':1});mini.append(pin);}for(const h of state.heroes){const dot=svgNode('circle',{id:'mini-hero-'+h.id,r:h===state.player?3.4:2.1,fill:h.team==='Light'?'#72dfff':'#ff777e'});mini.append(dot);const el=document.createElement('span');el.className='world-label hero-label '+(h.team==='Light'?'light':'dark')+(h===state.player?' player':'');const bar=document.createElement('i');el.append(bar);$('labels').append(el);heroLabels.set(h.id,{el,bar});}}
function bindCombatUI(){$('enter-bush').onclick=()=>{const e=entities.get(state.selected);if(e?.category==='bush')command({type:'move',point:xy(e.position)});};$('vision-team').onchange=e=>{heroVisibility.team=e.target.value;heroVisibility.apply();};$('ability-reveal').onclick=()=>command({type:'ability_used'});$('test-bush').onclick=()=>{const b=state.layout.bushes.find(b=>b.id===1),p=xy(b.position);state.player.position={...p,y:0};state.player.path=[];state.player.goal=null;state.updateVisibility();followHero();notify('Герой в кусте. Для союзников — 45%, для противников — невидим');};$('attack-combat').onclick=()=>{autoAttack=autoAttack===state.selected?null:state.selected;if(autoAttack)notify('Обычные атаки по выбранной цели включены');};$('approach-combat').onclick=()=>{let u=state.combatant(state.selected);const e=entities.get(state.selected);if(!u&&e?.category==='camp')u=[...state.neutrals.values()].find(n=>n.camp===e.properties.camp_index);if(!u)return;const p=state.nav.nearest(u.position,11);if(p)command({type:'move',point:p});};$('test-blessing').onclick=()=>state.grantDawnBlessing('Light');$('test-wave').onclick=()=>state.advanceTo(state.nextWave);}
function updateCombat(){if(autoAttack!==null){const t=state.combatant(autoAttack);if(!t?.alive)autoAttack=null;else if(state.time>=state.player.nextAttack){const r=state.issue({type:'combat_attack',target:autoAttack});if(!r.ok){notify(r.reason);autoAttack=null;}}}const selected=state.combatant(state.selected);$('combat-status').textContent=selected?(selected.alive?`${Math.ceil(selected.health)} / ${Math.ceil(selected.maxHealth)} HP`:`${selected.state==='Dormant'?'Появление':'Возрождение'}: ${mmss(Math.max(0,(selected.respawnAt??selected.spawnAt??state.time)-state.time))}`):'';$('attack-combat').textContent=autoAttack===state.selected?'Остановить атаки':'Атаковать цель';const alive=[...state.minions.values()].filter(u=>u.alive);$('wave-status').textContent=state.winner?(state.winner==='Light'?'Победа Света':'Победа Тьмы'):`Волна ${state.waveNumber} · следующая ${mmss(state.nextWave-state.time)}`;$('unit-counts').textContent=`Синие ${alive.filter(u=>u.team==='Light').length} · Красные ${alive.filter(u=>u.team==='Dark').length} · Нейтралы ${[...state.neutrals.values()].filter(n=>n.alive).length}/26`;$('blessing-status').textContent=state.blessings.Light?`Рассвет: усилены следующие ${state.blessings.Light} волны`:'';}
function mmss(t){const s=Math.max(0,Math.ceil(t));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
function updatePlaytest(t){const h=state.player,phase=state.bridge;$('match-clock').textContent=mmss(Math.floor(state.time));$('bridge-status').textContent=phase.active<0?'Оба моста закрыты':phase.active===0?'Рассвет открыт':'Сумерки открыты';$('bridge-countdown').textContent=(phase.active<0?'Открытие Рассвета через ':phase.warning?'Закрытие через ':'Смена мостов через ')+mmss(phase.remaining);document.querySelector('.match-status').classList.toggle('warning',phase.warning);$('hero-hp').style.width=`${h.health/h.maxHealth*100}%`;$('hero-mana').style.width=`${h.mana/h.maxMana*100}%`;$('hero-hp-text').textContent=`${Math.ceil(h.health)} / ${h.maxHealth}`;$('hero-mana-text').textContent=`${Math.ceil(h.mana)} / ${h.maxMana}`;const healing=state.fountains.some(f=>f.team===h.team&&dist(h.position,f.position)<=f.radius);$('hero-state').textContent=!h.alive?'Возрождение '+mmss(h.respawnAt-state.time):h.ejection?'На берег':healing?'Лечение':h.moving?'В пути':'Готов';
 for(let i=0;i<2;i++){const pin=$('mini-bridge-'+i);if(pin){pin.setAttribute('opacity',phase.active===i?'1':'.25');pin.classList.toggle('warning',phase.active===i&&phase.warning);}const mat=palette.find(m=>m.name===(i===0?'DawnGlow':'DuskGlow'));if(mat)mat.emissiveIntensity=phase.active===i?(phase.warning&&!reduced?(.25+(Math.sin(state.time*12)+1)*.7):.95):.12;}
 for(const hero of state.heroes){const dot=$('mini-hero-'+hero.id);dot?.setAttribute('cx',hero.position.x);dot?.setAttribute('cy',hero.position.z);dot?.setAttribute('visibility',heroVisibility.visible(hero)?'visible':'hidden');const label=heroLabels.get(hero.id);if(label){tmp.set(hero.position.x,state.renderHeight(hero.position)+3,hero.position.z).project(camera);label.el.style.visibility=heroVisibility.visible(hero)&&tmp.z>-1&&tmp.z<1&&Math.abs(tmp.x)<1.05&&Math.abs(tmp.y)<1.05?'visible':'hidden';label.el.style.left=`${(tmp.x*.5+.5)*innerWidth}px`;label.el.style.top=`${(-tmp.y*.5+.5)*innerHeight}px`;label.bar.style.width=`${hero.health/hero.maxHealth*100}%`;}}
 const selectedHero=state.combatant(state.selected);if(selectedHero&&state.heroById.has(selectedHero.id)&&!heroVisibility.visible(selectedHero))$('close-selection').click();else if(selectedHero&&selectionRing){selectionRing.position.set(selectedHero.position.x,state.renderHeight(selectedHero.position)+.2,selectedHero.position.z);selectionRing.visible=selectedHero.alive;}
 const alive=new Set();for(const p of [...state.projectiles,...state.combatProjectiles]){alive.add(p.id);let go=projectileMeshes.get(p.id);if(!go){go=new THREE.Group();const mesh=new THREE.Mesh(new THREE.SphereGeometry(p.large?.36:.22,8,6),new THREE.MeshBasicMaterial({color:p.team==='Light'?'#77edff':'#ff637e'}));mesh.position.y=1.5;go.add(mesh);world.add(go);projectileMeshes.set(p.id,go);}go.position.set(p.position.x,0,p.position.z);if(p.origin){const f=Math.min(1,dist(p.position,p.origin)/(p.span||1));go.children[0].position.y=THREE.MathUtils.lerp(p.visualFrom,p.visualTo,f);}}for(const [id,go]of projectileMeshes)if(!alive.has(id)){world.remove(go);for(const m of go.children){m.geometry.dispose();m.material.dispose();}projectileMeshes.delete(id);}
 while(state.events.length){const event=state.events.shift();if(event.kind!=='eject'||event.hero===h.id)notify(event.text);}
}

